import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, color, uv, positionLocal, mul, add, mix, fract, sin } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const cleanup = () => {
    gsap.killTweensOf(group);
    group.children.forEach(child => gsap.killTweensOf(child));
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  group.userData.cleanup = cleanup;
  group.userData.handlers = {};

  // Background plate: 7 x 5.5 with vertical gradient and grain
  const bgGeo = new THREE.PlaneGeometry(7, 5.5);
  const bgMat = new MeshBasicNodeMaterial();

  const grad = mix(
    color(new THREE.Color('#0b0b10')),
    color(new THREE.Color('#14141a')),
    add(uv().y, 0.5)
  );

  const grain = fract(
    mul(
      sin(mul(positionLocal.x, 12.9898) + mul(positionLocal.y, 78.233)),
      43758.5453
    )
  );

  bgMat.colorNode = mix(grad, grain, 0.015);

  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.z = -0.01;
  group.add(bgMesh);

  // Text content with fallbacks
  const text = config.textContent || {};

  // Helper to create and animate text blocks
  const createTextBlock = (content, fontConfig, position, delay) => {
    const mesh = ctx.fontAtlas.createText(content, fontConfig);

    mesh.position.copy(position);
    mesh.position.y += 0.4; // Rise-in offset

    if (mesh.material) {
      mesh.material.transparent = true;
      mesh.material.opacity = 0;
    }

    group.add(mesh);

    // Entrance animation
    gsap.to(mesh.position, {
      y: position.y,
      duration: 0.7,
      ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
      delay: delay / 1000
    });

    gsap.to(mesh.material, {
      opacity: 1,
      duration: 0.7,
      ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
      delay: delay / 1000
    });

    return mesh;
  };

  // Kicker
  createTextBlock(
    text.kicker || 'NOVA ATELIER / JOURNAL',
    { fontFamily: 'JetBrains Mono', fontSize: 18, fontWeight: 700, letterSpacing: 0.12, lineHeight: 1.4, align: 'left' },
    new THREE.Vector3(-3.1, 1.7, 0),
    0
  );

  // Hero line 1
  createTextBlock(
    text.hero1 || 'PRECISION IS',
    { fontFamily: 'Lora', fontSize: 124, fontWeight: 600, letterSpacing: -0.015, lineHeight: 0.98, align: 'left' },
    new THREE.Vector3(-3.1, 0.9, 0),
    80
  );

  // Hero line 2
  createTextBlock(
    text.hero2 || 'A HABIT.',
    { fontFamily: 'Lora', fontSize: 124, fontWeight: 600, letterSpacing: -0.015, lineHeight: 0.98, align: 'left' },
    new THREE.Vector3(-3.1, 0.25, 0),
    160
  );

  // Hero letterpress shadow 1
  const heroShadow1 = ctx.fontAtlas.createText('PRECISION IS', {
    fontFamily: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.015,
    lineHeight: 0.98,
    color: '#16161d',
    align: 'left'
  });
  heroShadow1.position.set(-3.1, 0.9 - 0.02, -0.02);
  heroShadow1.position.y += 0.4;
  if (heroShadow1.material) {
    heroShadow1.material.transparent = true;
    heroShadow1.material.opacity = 0;
  }
  group.add(heroShadow1);

  gsap.to(heroShadow1.position, {
    y: 0.9 - 0.02,
    duration: 0.7,
    ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
    delay: 0.08
  });

  gsap.to(heroShadow1.material, {
    opacity: 1,
    duration: 0.7,
    ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
    delay: 0.08
  });

  // Hero letterpress shadow 2
  const heroShadow2 = ctx.fontAtlas.createText('A HABIT.', {
    fontFamily: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.015,
    lineHeight: 0.98,
    color: '#16161d',
    align: 'left'
  });
  heroShadow2.position.set(-3.1, 0.25 - 0.02, -0.02);
  heroShadow2.position.y += 0.4;
  if (heroShadow2.material) {
    heroShadow2.material.transparent = true;
    heroShadow2.material.opacity = 0;
  }
  group.add(heroShadow2);

  gsap.to(heroShadow2.position, {
    y: 0.25 - 0.02,
    duration: 0.7,
    ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
    delay: 0.16
  });

  gsap.to(heroShadow2.material, {
    opacity: 1,
    duration: 0.7,
    ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
    delay: 0.16
  });

  // Accent underline rule: 2.2 x 0.05 units, #ff2a38 emissive
  const ruleGeo = new THREE.PlaneGeometry(2.2, 0.05);
  const ruleMat = new MeshBasicNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.2,
    side: THREE.DoubleSide
  });
  const ruleMesh = new THREE.Mesh(ruleGeo, ruleMat);
  ruleMesh.position.set(-2.0, -0.15, 0.01);
  ruleMesh.scale.x = 0;
  group.add(ruleMesh);

  // Rule draws after hero lands (0.7s + 0.16s = 0.86s)
  gsap.to(ruleMesh.scale, {
    x: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
    delay: 0.86
  });

  // Body paragraph
  createTextBlock(
    text.body || 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
    { fontFamily: 'JetBrains Mono', fontSize: 26, fontWeight: 400, letterSpacing: 0, lineHeight: 1.55, maxWidth: 4.5, align: 'left' },
    new THREE.Vector3(-3.1, -0.8, 0),
    240
  );

  // Caption
  createTextBlock(
    text.caption || 'ISSUE 12 / JULY 2026',
    { fontFamily: 'JetBrains Mono', fontSize: 18, fontWeight: 400, letterSpacing: 0.08, lineHeight: 1.4, align: 'left' },
    new THREE.Vector3(-3.1, -1.9, 0),
    320
  );

  return group;
}
